import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  // ✅ Modal states
  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm"); // confirm | success | error
  const [selectedCandidate, setSelectedCandidate] = useState(null);

  // Fetch candidates
  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        console.error("Error fetching candidates:", error);
        setModalMessage("Failed to load candidates.");
        setModalType("error");
        setShowModal(true);
      } finally {
        setLoading(false);
      }
    };

    fetchCandidates();
  }, []);

  // 🟢 Open Modal
  const handleVote = (candidateId) => {
    if (submitting) return;
    setSelectedCandidate(candidateId);
    setModalType("confirm");
    setModalMessage("Are you sure you want to vote? This cannot be changed.");
    setShowModal(true);
  };

  // 🟢 Confirm Vote
  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/votes`,
        { candidateId: selectedCandidate },
        {
          headers: {
            Authorization: `Bearer ${auth?.token}`,
          },
        }
      );

      setModalType("success");
      setModalMessage("✅ Vote cast successfully!");
    } catch (error) {
      console.error("Vote error:", error);
      setModalType("error");
      setModalMessage("❌ Vote failed or you already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  // Group candidates
  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  if (loading) {
    return (
      <div style={{ padding: 40, textAlign: "center" }}>
        <h2>Loading candidates...</h2>
      </div>
    );
  }

  if (candidates.length === 0) {
    return (
      <div style={{ padding: 40, textAlign: "center" }}>
        <h2>No candidates available.</h2>
      </div>
    );
  }

  return (
    <div style={{ padding: 40, maxWidth: 1200, margin: "auto" }}>
      <h1 style={{ textAlign: "center", marginBottom: 40 }}>
        Student Election 2026
      </h1>

      {Object.entries(groupedCandidates).map(([position, list]) => (
        <div key={position} style={{ marginBottom: 50 }}>
          <h2 style={{ marginBottom: 20 }}>{position}</h2>

          <div style={{ display: "flex", flexWrap: "wrap", gap: 25 }}>
            {list.map((candidate) => (
              <div
                key={candidate._id}
                style={{
                  width: 300,
                  backgroundColor: "#ffffff",
                  borderRadius: 15,
                  padding: 20,
                  boxShadow: "0 8px 20px rgba(0,0,0,0.08)",
                }}
              >
                {candidate.image && (
                  <img
                    src={`${API_URL}/${candidate.image}`}
                    alt={`${candidate.firstName} ${candidate.lastName}`}
                    style={{
                      width: "100%",
                      height: 200,
                      objectFit: "cover",
                      borderRadius: 10,
                      marginBottom: 15,
                    }}
                  />
                )}

                <h3>
                  {candidate.firstName} {candidate.lastName}
                </h3>

                <p style={{ fontSize: 14 }}>
                  🎓 {candidate.yearLevel} - {candidate.block}
                </p>

                <p style={{ fontSize: 14, minHeight: 60 }}>
                  {candidate.description}
                </p>

                <button
                  onClick={() => handleVote(candidate._id)}
                  disabled={submitting}
                  style={{
                    marginTop: 15,
                    padding: "10px",
                    width: "100%",
                    backgroundColor: "#6366f1",
                    color: "#fff",
                    border: "none",
                    borderRadius: 8,
                    fontWeight: "600",
                    cursor: "pointer",
                  }}
                >
                  Vote
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}

      {/* ✅ MODAL */}
      {showModal && (
        <div style={modalStyles.overlay}>
          <div style={modalStyles.modal}>
            <h3 style={{ marginBottom: 15 }}>
              {modalType === "confirm"
                ? "Confirm Vote"
                : modalType === "success"
                ? "Success"
                : "Error"}
            </h3>

            <p style={{ marginBottom: 25 }}>{modalMessage}</p>

            {modalType === "confirm" ? (
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <button
                  style={modalStyles.cancel}
                  onClick={() => setShowModal(false)}
                >
                  Cancel
                </button>

                <button
                  style={modalStyles.confirm}
                  onClick={confirmVote}
                  disabled={submitting}
                >
                  {submitting ? "Submitting..." : "Confirm"}
                </button>
              </div>
            ) : (
              <button
                style={modalStyles.confirm}
                onClick={() => setShowModal(false)}
              >
                OK
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// 🎨 Modal Styles
const modalStyles = {
  overlay: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    backgroundColor: "rgba(0,0,0,0.5)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    zIndex: 999,
  },
  modal: {
    width: 350,
    backgroundColor: "#ffffff",
    padding: 30,
    borderRadius: 10,
    textAlign: "center",
    boxShadow: "0 10px 25px rgba(0,0,0,0.2)",
  },
  cancel: {
    padding: "10px 20px",
    border: "none",
    backgroundColor: "#ccc",
    borderRadius: 6,
    cursor: "pointer",
  },
  confirm: {
    padding: "10px 20px",
    border: "none",
    backgroundColor: "#6366f1",
    color: "#fff",
    borderRadius: 6,
    cursor: "pointer",
  },
};

export default VotingPage;
